// WORKER - Calificar Contacto
// Tarea atomica y deterministica: no usa IA, no llama APIs, no escribe en ningun lado.
// Contrato de salida (siempre el mismo): { status: 'ok' | 'error', data, error }

const DOMINIOS_PERSONALES = ['gmail.com', 'hotmail.com', 'outlook.com', 'yahoo.com', 'yahoo.com.ar', 'icloud.com', 'live.com', 'proton.me', 'protonmail.com'];
const PALABRAS_URGENCIA = ['urgente', 'urgencia', 'cuanto antes', 'esta semana', 'ya mismo', 'inmediato', 'para hoy', 'lo antes posible'];

const salida = [];

for (const item of $input.all()) {
  // El Manager manda { lead: {...} }. Si llegara plano, tambien funciona.
  const contacto = item.json.contacto ?? item.json;
  const email = String(contacto.email ?? '').trim().toLowerCase();

  // El Worker no muere: devuelve status 'error' y deja que el Manager decida.
  if (!email.includes('@')) {
    salida.push({ json: {
      status: 'error',
      data: null,
      error: { code: 'CONTACTO_SIN_EMAIL', mensaje: 'El Worker necesita un email valido para calificar el CONTACTO.' }
    }});
    continue;
  }

  const motivos = [];
  let score = 0;

  const dominio = email.split('@')[1] ?? '';
  const esCorporativo = dominio !== '' && !DOMINIOS_PERSONALES.includes(dominio);
  if (esCorporativo) { score += 25; motivos.push('email corporativo (+25)'); }

  if (String(contacto.familia ?? '').trim() !== '') { score += 30; motivos.push('familia declarada (+30)'); }



  const texto = String(contacto.mensaje ?? '').toLowerCase();
  if (PALABRAS_URGENCIA.some(function (p) { return texto.includes(p); })) { score += 35; motivos.push('senal de urgencia en el mensaje (+35)'); }

  score = Math.min(score, 100);

  let temperatura, owner, sla_horas;
  if (score >= 70) { temperatura = 'HOT'; owner = 'ventas-senior'; sla_horas = 2; }
  else if (score >= 40) { temperatura = 'WARM'; owner = 'ventas'; sla_horas = 24; }
  else { temperatura = 'COLD'; owner = 'nurturing'; sla_horas = 72; }

  salida.push({ json: {
    status: 'ok',
    error: null,
    data: {
      score: score,
      temperatura: temperatura,
      owner: owner,
      sla_horas: sla_horas,
      email_corporativo: esCorporativo,
      motivos: motivos
    }
  }});
}

return salida;
